// Subset Material Icons to the ligatures used by the WebUI.
// Regenerated by `npm run build:icons`; the full font is in scripts/assets.
const fs = require('fs');
const path = require('path');
const fontkit = require('fontkit');
const fontverter = require('fontverter');

const ROOT = path.resolve(__dirname, '..');
const FULL_FONT = path.join(ROOT, 'scripts/assets/material-icons-full.woff2');
const OUTPUTS = [
  path.join(ROOT, 'src/webroot/assets/material-icons-outlined.woff2'),
];

// Safety net for icons composed at runtime.
const COMMON_ICONS = `
add arrow_forward arrow_upward arrow_downward chevron_left expand_more expand_less
edit delete done_all visibility person account_circle security shield verified sync
update file_download file_upload create_new_folder note_add add_circle remove_circle
clear filter_list sort play_arrow pause stop construction report help lock_open memory
sd_card usb cable signal_cellular_alt battery_full power_settings_new rocket_launch
speed date_range event calendar_today notifications campaign chat message email
cloud_sync system_update install_desktop file_copy folder_shared drive_file_move
`.trim().split(/\s+/);

const HB_MEMORY_MODE_WRITABLE = 2;
const HB_SUBSET_SETS_LAYOUT_FEATURE_TAG = 6;
const HB_SUBSET_FLAGS_NO_LAYOUT_CLOSURE = 0x00000200;

function HB_TAG(str) {
  return str.split('').reduce((a, ch) => (a << 8) + ch.charCodeAt(0), 0);
}

function walk(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === 'lang' || entry.name === 'assets') continue;
      out.push(...walk(full));
    } else if (/\.(html|ts)$/.test(entry.name) && !/\.test\.ts$/.test(entry.name)) {
      out.push(full);
    }
  }
  return out;
}

function isLigature(font, name) {
  try {
    const run = font.layout(name);
    return run.glyphs.length === 1;
  } catch {
    return false;
  }
}

function collectIconNames(font) {
  const candidates = new Set();
  const mdIcons = new Set();

  for (const file of walk(path.join(ROOT, 'src/webroot'))) {
    const text = fs.readFileSync(file, 'utf8');
    for (const match of text.matchAll(/<md-icon[^>]*>\s*([a-zA-Z0-9_]+)\s*<\/md-icon>/g)) {
      candidates.add(match[1]);
      mdIcons.add(match[1]);
    }
    for (let i = 0; i < text.length; i++) {
      const quote = text[i];
      if (quote !== "'" && quote !== '"') continue;
      let end = i + 1;
      while (end < text.length && text[end] !== quote && text[end] !== '\n') {
        if (text[end] === '\\') end++;
        end++;
      }
      if (text[end] === quote) {
        const value = text.slice(i + 1, end);
        if (value.length >= 2 && value.length <= 60) candidates.add(value);
        i = end;
      }
    }
  }

  const icons = new Set();
  for (const name of candidates) {
    if (isLigature(font, name)) icons.add(name);
  }
  for (const name of COMMON_ICONS) {
    if (isLigature(font, name)) icons.add(name);
  }

  const invalid = [...mdIcons].filter(name => !isLigature(font, name));
  if (invalid.length) {
    console.warn(`Warning: unknown <md-icon> ligatures: ${invalid.join(', ')}`);
  }

  return icons;
}

async function subsetByGlyphIds(fullBuffer, font, icons) {
  const glyphIds = new Set([0]);
  for (const name of icons) {
    const run = font.layout(name);
    if (run.glyphs.length === 1 && run.glyphs[0]) glyphIds.add(run.glyphs[0].id);
    for (const char of name) {
      const glyph = font.glyphForCodePoint(char.codePointAt(0));
      if (glyph) glyphIds.add(glyph.id);
    }
  }
  const space = font.glyphForCodePoint(32);
  if (space) glyphIds.add(space.id);

  const sfnt = await fontverter.convert(fullBuffer, 'truetype');
  const wasmPath = require.resolve('harfbuzzjs/dist/harfbuzz-subset.wasm');
  const wasm = await WebAssembly.instantiate(fs.readFileSync(wasmPath));
  const hb = wasm.instance.exports;
  hb._initialize();
  const heap = () => new Uint8Array(hb.memory.buffer);

  const input = hb.hb_subset_input_create_or_fail();
  if (!input) throw new Error('hb_subset_input_create_or_fail failed');
  const fontBuffer = hb.malloc(sfnt.byteLength);
  heap().set(new Uint8Array(sfnt), fontBuffer);
  const blob = hb.hb_blob_create(fontBuffer, sfnt.byteLength, HB_MEMORY_MODE_WRITABLE, 0, 0);
  const face = hb.hb_face_create(blob, 0);
  hb.hb_blob_destroy(blob);

  try {
    const layoutFeatures = hb.hb_subset_input_set(input, HB_SUBSET_SETS_LAYOUT_FEATURE_TAG);
    hb.hb_set_clear(layoutFeatures);
    hb.hb_set_invert(layoutFeatures);

    const glyphSet = hb.hb_subset_input_glyph_set(input);
    hb.hb_set_clear(glyphSet);
    for (const id of glyphIds) hb.hb_set_add(glyphSet, id);

    const flags = hb.hb_subset_input_get_flags(input) | HB_SUBSET_FLAGS_NO_LAYOUT_CLOSURE;
    hb.hb_subset_input_set_flags(input, flags);

    const subset = hb.hb_subset_or_fail(face, input);
    if (!subset) throw new Error('hb_subset_or_fail failed');

    try {
      const result = hb.hb_face_reference_blob(subset);
      try {
        const offset = hb.hb_blob_get_data(result, 0);
        const length = hb.hb_blob_get_length(result);
        if (!length) throw new Error('empty subset blob');
        const out = Buffer.from(heap().subarray(offset, offset + length));
        return await fontverter.convert(out, 'woff2');
      } finally {
        hb.hb_blob_destroy(result);
      }
    } finally {
      hb.hb_face_destroy(subset);
    }
  } finally {
    hb.hb_face_destroy(face);
    hb.free(fontBuffer);
    hb.hb_subset_input_destroy(input);
  }
}

async function main() {
  const fullBuffer = fs.readFileSync(FULL_FONT);
  const fullFont = fontkit.openSync(FULL_FONT);
  const icons = collectIconNames(fullFont);
  const subset = await subsetByGlyphIds(fullBuffer, fullFont, icons);

  const check = fontkit.create(subset);
  const broken = [...icons].filter(name => {
    const run = check.layout(name);
    return !(run.glyphs.length === 1 && run.glyphs[0] && run.glyphs[0].name === name);
  });
  if (broken.length) throw new Error(`Subset is missing ligatures: ${broken.join(', ')}`);

  for (const output of OUTPUTS) fs.writeFileSync(output, subset);
  console.log(
    `Material Icons subset: ${icons.size} icons, ${(subset.length / 1024).toFixed(1)} KB ` +
    `(from ${(fullBuffer.length / 1024).toFixed(1)} KB)`
  );
}

main().catch(error => {
  console.error(error);
  process.exit(1);
});
